/bin/bash -lc "python3 - <<'PY'
from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png')).astype(int)
conds={
 'blue':(im[:,:,2]-im[:,:,0]>30)&(im[:,:,2]>60),
 'satblue':(im[:,:,2]-im[:,:,0]>80)&(im[:,:,2]>100),
 'lightcool':(im.min(2)>120)&(im[:,:,2]-im[:,:,0]>15),
 'bright':im.mean(2)>180,
 'dark':im.mean(2)<65,
 'verydark':im.mean(2)<30,
 'reddark':(im[:,:,0]>im[:,:,2]*2)&(im.mean(2)<80),
}
def runs(a, minlen=2):
 p=np.flatnonzero(a); out=[]
 if len(p):
  cuts=np.r_[0,np.flatnonzero(np.diff(p)>1)+1,len(p)]
  for s,e in zip(cuts[:-1],cuts[1:]):
   if p[e-1]-p[s]+1>=minlen: out.append(f'{p[s]}-{p[e-1]}')
 return ','.join(out)
for y in range(0,251,5):
 print(f'y={y:3}',end=' ')
 for n,c in conds.items():
  r=runs(c[y],2)
  if r: print(f'{n}[{r}]',end=' ')
 print()
PY"
